from (values
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,1,$$Em conceitos e princípios da extensão, o núcleo do estudo é relacionar conhecimento acadêmico a demandas e saberes produzidos fora da universidade. A ideia precisa ser entendida como processo situado: depende de objetivos, sujeitos, contexto e evidências, não apenas de uma definição.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,2,$$Comece pelo problema concreto. Pergunte como tratar extensão como atividade voluntária desconectada do currículo e da formação aparece em uma situação real, quais atores participam e que decisões precisam ser tomadas para transformar a prática.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,3,$$Os conceitos deste tópico se conectam. Observe a relação entre finalidade educativa, planejamento, conhecimentos mobilizados e avaliação; separar essas dimensões pode esconder como o processo realmente funciona.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,4,$$Imagine uma situação de trabalho, comunidade ou sala de aula relacionada ao tema. A análise deve mostrar tratar extensão como atividade voluntária desconectada do currículo e da formação, tornando visível por que determinada escolha pedagógica faz sentido naquele contexto.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,5,$$Uma boa leitura identifica evidências: registros, observações, produções dos estudantes, falas dos participantes, documentos ou resultados. O tipo de evidência deve combinar com a pergunta que orienta a ação.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,6,$$Um erro frequente é undefined. Esse problema aparece quando se aplica uma receita antes de compreender contexto, finalidade e limites. O antídoto é justificar as escolhas e acompanhar suas consequências.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,7,$$No aprofundamento, compare alternativas e condições. Conceitos e princípios da extensão não se resume a um procedimento único; diferentes contextos podem exigir estratégias distintas, desde que preservem os princípios centrais.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,8,$$Na prática profissional, transforme o conceito em um pequeno ciclo: diagnosticar, planejar, agir, registrar, analisar e revisar. Esse ciclo permite aprender com a própria intervenção e ajustar o próximo passo.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,9,$$A síntese pode ser organizada em quatro perguntas: para quê fazemos isso, com quem, como e com que evidência saberemos se funcionou? Responder às quatro dá consistência ao estudo de conceitos e princípios da extensão.$$),
($$Extensão Universitária em Educação$$,$$Conceitos e princípios da extensão$$,10,$$Para revisar, explique o conceito com suas próprias palavras e crie um exemplo ligado a tratar extensão como atividade voluntária desconectada do currículo e da formação. Depois diga qual seria a principal limitação da sua proposta e que informação ajudaria a melhorá-la.$$),
($$Extensão Universitária em Educação$$,$$Universidade e comunidade$$,1,$$Em universidade e comunidade, o núcleo do estudo é planejar atividades com participação real dos sujeitos envolvidos e reconhecer seus conhecimentos. A ideia precisa ser entendida como processo situado: depende de objetivos, sujeitos, contexto e evidências, não apenas de uma definição.$$),
