($$Pedagogia em Espaços Não Escolares$$,$$Competências profissionais do pedagogo$$,10,$$Para revisar, explique o conceito com suas próprias palavras e crie um exemplo ligado a tratar competência como lista fixa de tarefas independente do contexto de trabalho. Depois diga qual seria a principal limitação da sua proposta e que informação ajudaria a melhorá-la.$$)
) v(discipline,topic,position,content)
join public.disciplines d on d.name=v.discipline
join public.topics t on t.discipline_id=d.id and t.name=v.topic
join public.materials m on m.topic_id=t.id
where ms.material_id=m.id and ms.position=v.position;

insert into public.material_citations(material_id,source_id,citation_label)
select m.id,s.id,x.label
from (values
 ('Extensão Universitária em Educação','Resolução CNE/CES nº 7, de 18 de dezembro de 2018 — Diretrizes para a Extensão na Educação Superior','CNE/CES — Extensão'),
 ('Educação Profissional e Formação ao Longo da Vida','Resolução CNE/CP nº 1, de 5 de janeiro de 2021 — Diretrizes Curriculares Nacionais Gerais para a Educação Profissional e Tecnológica','CNE/CP — EPT 2021'),
 ('Educação Profissional e Formação ao Longo da Vida','Lei nº 9.394/1996 — Lei de Diretrizes e Bases da Educação Nacional','LDB — EPT'),
 ('Ensino de Ciências nos Anos Iniciais','Base Nacional Comum Curricular — Educação Infantil e Ensino Fundamental','BNCC — Ciências'),
 ('Pedagogia em Espaços Não Escolares','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia — atuação profissional')
) x(discipline,source_title,label)
join public.disciplines d on d.name=x.discipline
join public.topics t on t.discipline_id=d.id
join public.materials m on m.topic_id=t.id
join public.sources s on s.title=x.source_title
where not exists(select 1 from public.material_citations mc where mc.material_id=m.id and mc.source_id=s.id);